1: import { Injectable } from '@angular/core';
2: import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
3: import { environment } from '../../environments/environment';
4: import { catchError, map } from 'rxjs/operators';
5: import { HttpErrorManager } from './errorManager.service'
6: 
7: /**
8:  * This class manage the http connections with internal REST services. Use the response format {
9:  *  Code: 'xxxxx',
10:  *  Body: 'Some Data' (this element is returned if the request is success)
11:  *  ...
12:  * }
13:  */
14: @Injectable({
15:   providedIn: 'root',
16: })
17: export class RequestManager {
18:   private path!: string;
19:   public httpOptions: any;
20:   constructor(
21:     private http: HttpClient, 
22:     private errManager: HttpErrorManager
23:   ) {
24:     const acces_token = window.localStorage.getItem('access_token');
25:     if (acces_token !== null) {
26:       this.httpOptions = {
27:         headers: new HttpHeaders({
28:           'Content-Type': 'application/json',
29:           'Authorization': `Bearer ${acces_token}`,
30:         }),
31:       }
32:     }
33:   }
34: 
35: 
36:   /**
37:    * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
38:    * @param service: string
39:    */
40:     public setPath(service: keyof typeof environment) {
41:         this.path = environment[service] as string;
42:     }
43: 
44: 
45:   /**
46:    * Perform a GET http request
47:    * @param endpoint service's end-point
48:    * @param params (an Key, Value object with que query params for the request)
49:    * @returns Observable<any>
50:    */
51:   get(endpoint: string) {
52:     return this.http.get<any>(`${this.path}${endpoint}`, this.httpOptions).pipe(
53:       map(
54:         (res: any) => {
55:           if (res.hasOwnProperty('Body')) {
56:             return res['Body'];
57:           } else {
58:             return res;
59:           }
60:         },
61:       ),
62:       catchError(this.errManager.handleError.bind(this)),
63:     );
64:   }
65: 
66:   /**
67:    * Perform a POST http request
68:    * @param endpoint service's end-point
69:    * @param element data to send as JSON
70:    * @returns Observable<any>
71:    */
72:   post(endpoint: string, element: any) {
73:     return this.http.post<any>(`${this.path}${endpoint}`, element, this.httpOptions).pipe(
74:       catchError(this.errManager.handleError),
75:     );
76:   }
77: 
78:   /**
79:    * Perform a POST http request
80:    * @param endpoint service's end-point
81:    * @param element data to send as JSON
82:    * @returns Observable<any>
83:    */
84:   post_file(endpoint: string, element: any) {
85:     return this.http.post<any>(`${this.path}${endpoint}`, element, {    headers: new HttpHeaders({
86:       'Content-Type': 'multipart/form-data',
87:   })}).pipe(
88:       catchError(this.errManager.handleError),
89:     );
90:   }
91: 
92:   /**
93:    * Perform a PUT http request
94:    * @param endpoint service's end-point
95:    * @param element data to send as JSON, With the id to UPDATE
96:    * @returns Observable<any>
97:    */
98:   put(endpoint: string, element: { Id: any; }) {
99:     const path = (element.Id) ? `${this.path}${endpoint}/${element.Id}` : `${this.path}${endpoint}`;
100:     return this.http.put<any>(path, element, this.httpOptions).pipe(
101:       catchError(this.errManager.handleError),
102:     );
103:   }
104: 
105:   /**
106:    * Perform a DELETE http request
107:    * @param endpoint service's end-point
108:    * @param id element's id for remove
109:    * @returns Observable<any>
110:    */
111:   delete(endpoint: string, id: any) {
112:     return this.http.delete<any>(`${this.path}${endpoint}/${id}`, this.httpOptions).pipe(
113:       catchError(this.errManager.handleError),
114:     );
115:   }
116: 
117:   get_soap(endpoint: string) {
118:     return this.http.get(`${this.path}${endpoint}`,
119:       {
120:         headers: new HttpHeaders({
121:           'Content-Type': 'multipart/form-data'
122:         })
123:       });
124:   }
125: };

